#include <iostream>
#include <array>

void optionAlpha(int val) {
    std::cout << "Option Alpha: square = " << (val * val) << "\n";
}

void optionBeta(int val) {
    std::cout << "Option Beta: double = " << (val * 2) << "\n";
}

void optionGamma(int val) {
    std::cout << "Option Gamma: value = " << val << "\n";
}

int main() {
    // Array of function pointers in C++17
    using ActionFn = void(*)(int);
    std::array<ActionFn, 3> actions = { optionAlpha, optionBeta, optionGamma };

    int choice = 0;
    int payload = 0;

    while (std::cin >> choice >> payload) {
        if (choice < 0 || choice >= static_cast<int>(actions.size())) {
            std::cout << "End of menu operations.\n";
            break;
        }
        // Invoke via function pointer dereference
        (*actions[choice])(payload);
    }

    return 0;
}

#include <iostream>
#include <string_view>

// DCL13-C: Pass read-only pointers with const qualifier
void displayMessage(const char *msg) {
    // EXP34-C: Check against null pointer before dereferencing
    if (msg == nullptr) {
        std::cout << "Error: Null pointer provided!\n";
        return;
    }
    std::cout << "Message: " << msg << "\n";
}

// C++17 preferred idiomatic approach using string_view
void displayModern(std::string_view sv) {
    std::cout << "Modern view: " << sv << "\n";
}

int main() {
    const char valid[] = "Secure data transmission";
    const char *invalid = nullptr;

    displayMessage(valid);
    displayMessage(invalid);

    displayModern("C++17 safe string");

    return 0;
}
